// Exercise the header-only template mmkv::unused with several types
int vi = (int)(*FUZZ_PARAM(unsigned int) % 1000);
mmkv::unused<int>(vi);

double vd = (double)(*FUZZ_PARAM(unsigned int) % 1000) / 3.14159;
mmkv::unused<double>(vd);

std::string vs = FUZZ_PARAM_STR();
mmkv::unused<const std::string &>(vs);

// Also try a pointer type
void *vp = nullptr;
mmkv::unused<void *>(vp);

// Validation: Template accepts any type by const-ref; no runtime effects expected.

// Create buffers of varying sizes within performance limits
size_t len_small = (size_t)(*FUZZ_PARAM(unsigned int) % 64);
mmkv::MMBuffer buf_small(len_small);

size_t len_mid = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
mmkv::MMBuffer buf_mid(len_mid);

size_t len_zero = 0;
mmkv::MMBuffer buf_zero(len_zero);

// Basic property checks: length matches constructor argument
FUZZ_ASSERT(buf_small.length() == len_small, "MMBuffer length mismatch (small)");
FUZZ_ASSERT(buf_mid.length() == len_mid, "MMBuffer length mismatch (mid)");
FUZZ_ASSERT(buf_zero.length() == 0, "MMBuffer length mismatch (zero)");

// Validation: Constructs MMBuffer with several lengths and asserts length invariants.

// Explicitly allocate and then manually invoke destructor safely
size_t len = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
void *raw = ::operator new(sizeof(mmkv::MMBuffer));
mmkv::MMBuffer *p = new(raw) mmkv::MMBuffer(len);
// After construction, call the destructor explicitly to target ~MMBuffer
p->~MMBuffer();
// Release only the raw storage (no double-destroy)
::operator delete(raw);

// Validation: Destructor is directly invoked; no use-after-destroy and no double free.

// Create buffers around small-buffer optimization thresholds (unknown exact threshold)
size_t len1 = (size_t)(*FUZZ_PARAM(unsigned int) % 64);
mmkv::MMBuffer b1(len1);
bool s1 = b1.isStoredOnStack();
mmkv::unused<bool>(s1);

size_t len2 = (size_t)((*FUZZ_PARAM(unsigned int) % 2048) + 64);
mmkv::MMBuffer b2(len2);
bool s2 = b2.isStoredOnStack();
mmkv::unused<bool>(s2);

// Zero-length buffer behavior
mmkv::MMBuffer bz(0);
bool sz = bz.isStoredOnStack();
mmkv::unused<bool>(sz);

// Validation: Calls isStoredOnStack() on multiple sizes; no strict expectations enforced.

size_t len = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
mmkv::MMBuffer b(len);
void *ptr = b.getPtr();
// Pointer may be null for zero-length buffers; if non-null and len>0, touch within bounds
if (ptr && len > 0) {
    // Write a single byte to validate writability when owned by buffer
    static_cast<unsigned char*>(ptr)[0] ^= (unsigned char)(*FUZZ_PARAM(unsigned int) & 0xFF);
}

// Also test zero-length case explicitly
mmkv::MMBuffer bz(0);
void *p0 = bz.getPtr();
mmkv::unused<void *>(p0);

// Validation: Respects getPtr() lifetime; only touches memory when length > 0.

size_t len = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
mmkv::MMBuffer b(len);
FUZZ_ASSERT(b.length() == len, "length() must equal constructor size");

// Check after a no-op detach/reattach pattern does not alter length
mmkv::MMBuffer c((size_t)0);
FUZZ_ASSERT(c.length() == 0, "zero buffer length invariant");

// Validation: Verifies length() equals the constructed size and zero-length invariant.

size_t len = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
if (len == 0) { len = 1; }
mmkv::MMBuffer b(len);
void *before = b.getPtr();
// Detach transfers ownership of underlying memory out of the buffer
b.detach();
// Postcondition specifics are internal; ensure we don't use 'before' through b as owner anymore
// We can still query length; it should remain the same per typical semantics
size_t l2 = b.length();
mmkv::unused<size_t>(l2);

// Validation: Exercises detach(); avoids relying on ownership, only inspects non-owning state.

// Construct two buffers and compare for equality
size_t len = (size_t)(*FUZZ_PARAM(unsigned int) % 128);
mmkv::MMBuffer a(len);
mmkv::MMBuffer b(len);

bool eq1 = (a == b);
mmkv::unused<bool>(eq1);

// If possible, mutate one to make contents differ and compare again
void *pa = a.getPtr();
if (pa && len > 0) {
    static_cast<unsigned char*>(pa)[len - 1] ^= 0x5A;
}
bool eq2 = (a == b);
mmkv::unused<bool>(eq2);

// Also compare different sizes
mmkv::MMBuffer c(len + 1);
bool eq3 = (a == c);
mmkv::unused<bool>(eq3);

// Validation: Covers equal-size equal/unequal content and unequal-size comparisons.

